#define TAO_INPUT_SCALE
#define TAO_DEVICE_ZERO_GRAD
#include "batch_train_graph.cuh"
#include "dual_state_initialization.hpp"
#include <cstdio>
int main(){using namespace tao::dual;try{Config c{2,16,8,16,32,261};auto cpu=initialize(c,713);BatchTrainGraph b(cpu,4);std::vector<std::unique_ptr<TrainGraph>>refs;for(int k=0;k<4;++k)refs.emplace_back(new TrainGraph(cpu));float logits_err=0,state_err=0;for(int t=0;t<3;++t){std::vector<unsigned>ids{unsigned(65+t),unsigned(70+t),unsigned(75+t),unsigned(80+t)};std::vector<bool>active{true,t<2,true,t>0},reset{t==0,t==0,t==1,t==1};auto y=b.step(ids,active,reset);auto actual=y->value.host();Vec seed(4*c.vocab,0);for(int k=0;k<4;++k){if(!active[k])continue;auto&r=*refs[k];if(reset[k])for(unsigned l=0;l<c.layers;++l){r.s[l]=r.tape.leaf(Vec(c.s,0));r.m[l]=r.tape.leaf(Vec(c.m,0));}auto z=r.step(ids[k]);auto expected=z->value.host();for(unsigned j=0;j<c.vocab;++j)logits_err=std::max(logits_err,std::abs(actual[k*c.vocab+j]-expected[j]));Vec grad(c.vocab,0);grad[10+t]=.1f;seed[k*c.vocab+10+t]=.1f;check(cudaMemcpy(z->grad.p,grad.data(),grad.size()*4,cudaMemcpyHostToDevice));}check(cudaMemcpy(y->grad.p,seed.data(),seed.size()*4,cudaMemcpyHostToDevice));}b.tape.backward();for(auto&r:refs)r->tape.backward();for(unsigned l=0;l<c.layers;++l){auto ss=b.s[l]->value.host(),mm=b.m[l]->value.host();for(int k=0;k<4;++k){auto s=refs[k]->s[l]->value.host(),m=refs[k]->m[l]->value.host();for(unsigned j=0;j<c.s;++j)state_err=std::max(state_err,std::abs(ss[k*c.s+j]-s[j]));for(unsigned j=0;j<c.m;++j)state_err=std::max(state_err,std::abs(mm[k*c.m+j]-m[j]));}}double error=0,base=0;float maxg=0;for(auto&kv:b.w){auto actual=kv.second->grad.host();Vec expected(actual.size(),0);for(auto&r:refs){auto g=r->w.at(kv.first)->grad.host();for(size_t i=0;i<g.size();++i)expected[i]+=g[i];}for(size_t i=0;i<actual.size();++i){if(!std::isfinite(actual[i]))throw std::runtime_error("nonfinite");double d=actual[i]-expected[i];error+=d*d;base+=double(expected[i])*expected[i];maxg=std::max(maxg,float(std::abs(d)));}}printf("logits_max=%.9g state_max=%.9g gradient_max=%.9g gradient_relative_l2=%.9g\n",logits_err,state_err,maxg,std::sqrt(error/base));if(logits_err>1e-4||state_err>1e-4||std::sqrt(error/base)>1e-4)return 1;return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 2;}}
